import './Login.css';
import NavigationBar from './NavigationBar';
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import React, { useState } from 'react';
import axios from 'axios';

const CreatePost = ({ userId }) => {

    // const [title, setTitle] = useState('');
    const [content, setContent] = useState('');
    const [error, setError] = useState('');
  
    const handleCreatePost = async (e) => {
      e.preventDefault();
  
      const postData = {
        user: { id: userId }, // Make sure userId is passed in as a prop or fetched
        content: content
        // title: title,
      };
  
      try {
        const response = await axios.post('/api/posts/create', postData);
        if (response.status === 200) {
          console.log('Post Created:', response.data);
        }
      } catch (err) {
        setError('Error creating post.');
      }
    };

    return(
        <div fluid>
            <NavigationBar />
            <Container style={{width:"100%", paddingTop:"1.5rem"}}>
                <Row>
                    <Col style={{paddingBottom:"1.5rem"}}>
                        <h1>Create</h1>
                    </Col>
                </Row>
                <Row style={{backgroundColor:"#282c34", padding:"10px", borderRadius:"30px"}}>
                    <Col style={{backgroundColor:"#787878", padding:"15px 30px", borderRadius:"25px"}}>
                    <form action="#" method="POST" onSubmit={handleCreatePost}>
                        {/* <div>
                                <label for="title">Title</label>
                            <div>
                                <input type="text" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Title" required/>
                            </div>
                        </div> */}
                        <div>
                                <label for="description">Content</label>
                            <div>
                                <textarea value={content} onChange={(e) => setContent(e.target.value)} placeholder="What's on your mind?" required/>
                            </div>
                            {error && <p style={{ color: 'red' }}>{error}</p>}
                        </div>
                        <div>
                            <button type="submit">Post</button>
                        </div>
                    </form>
                    </Col>
                </Row>
            </Container>
        </div>
    )
}

export default CreatePost;
